#!/usr/bin/env bash
# NEXUS CLAW + OpenCode + Ollama single-file installer
# Usage: bash install_nexus_claw_opencode.sh [install-directory]
set -Eeuo pipefail
APP_DIR="${1:-$HOME/NEXUS_CLAW}"
MODEL_NAME="nexus-claw:1.5b"
BASE_MODEL="qwen2.5-coder:1.5b"
say() { printf '\n[NEXUS CLAW] %s\n' "$*"; }
die() { printf '\n[FEHLER] %s\n' "$*" >&2; exit 1; }
command -v python3 >/dev/null 2>&1 || die "Python 3 fehlt."
command -v base64 >/dev/null 2>&1 || die "base64 fehlt."
if [[ -e "$APP_DIR" && -n "$(find "$APP_DIR" -mindepth 1 -maxdepth 1 -print -quit 2>/dev/null)" ]]; then
  printf 'Zielordner ist nicht leer: %s\nVorhandene Dateien werden nicht überschrieben.\n' "$APP_DIR" >&2
  exit 2
fi
mkdir -p "$APP_DIR"
TMP_ZIP="$(mktemp)"
trap 'rm -f "$TMP_ZIP"' EXIT
say "Entpacke eingebettetes Projekt ..."
base64 -d > "$TMP_ZIP" <<'NEXUS_CLAW_ZIP_BASE64'

NEXUS_CLAW_ZIP_BASE64
python3 - "$TMP_ZIP" "$APP_DIR" <<'PY'
import sys, zipfile
from pathlib import Path
archive, destination = Path(sys.argv[1]), Path(sys.argv[2])
with zipfile.ZipFile(archive) as z:
    root = Path("nexus_claw_ollama_qwen25_coder")
    for item in z.infolist():
        p = Path(item.filename)
        if p.is_absolute() or ".." in p.parts:
            raise SystemExit(f"Unsicherer Archivpfad abgelehnt: {item.filename}")
        relative = Path(*p.parts[1:]) if p.parts and p.parts[0] == root.name else p
        if not relative.parts:
            continue
        target = destination / relative
        if item.is_dir():
            target.mkdir(parents=True, exist_ok=True)
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(z.read(item))
PY
say "Schreibe OpenCode-Konfiguration ..."
cat > "$APP_DIR/opencode.json" <<'JSON'
{
  "$schema": "https://opencode.ai/config.json",
  "model": "ollama/nexus-claw:1.5b",
  "provider": {
    "ollama": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "Ollama (lokal)",
      "options": { "baseURL": "http://127.0.0.1:11434/v1" },
      "models": {
        "nexus-claw:1.5b": {
          "name": "NEXUS CLAW Qwen2.5 Coder 1.5B",
          "limit": { "context": 4096, "output": 2048 }
        },
        "qwen2.5-coder:1.5b": {
          "name": "Qwen2.5 Coder 1.5B (Basis)",
          "limit": { "context": 4096, "output": 2048 }
        }
      }
    }
  }
}
JSON
cat > "$APP_DIR/AGENTS.md" <<'AGENTS'
# NEXUS CLAW: Regeln für OpenCode
Sprache: Deutsch. Architektur: NEXUS → MODELL → AGENT → FÄHIGKEIT → WERKZEUG.

## Workflow
Anfrage → Analyse → Plan → Ausführung → Prüfung → Fertig.
Ziel und Erfolgskriterien bestimmen; Git-Status und Branch prüfen; kleine Änderungen durchführen; Tests, Diff und Seiteneffekte prüfen; echte Ergebnisse berichten.

## Sicherheit
- `main` und `master` schützen. Änderungen/Commits nur auf ausdrücklich erlaubten `nexus-dev-*`-Branches.
- Niemals automatisch pushen.
- `.env`, Tokens, Passwörter, private Schlüssel und Signaturdateien niemals ausgeben oder protokollieren.
- Vor externen, irreversiblen, destruktiven oder datenverändernden Aktionen Bestätigung einholen.
- Unbekannte Skripte und Skills zuerst prüfen; keine Berechtigungen umgehen.
- Sandbox oder separaten Git-Worktree bevorzugen.
- Maximal drei Reparaturversuche pro Fehlerklasse, danach SAFE_STOP.
- Bei fehlenden Rechten, unklarer Repository-Lage oder wiederholten Fehlern anhalten.

## Ergebniswahrheit
- Nie behaupten, Build, Test, Gameplay-Lauf, Commit oder Push sei erfolgreich, wenn kein echtes Ergebnis vorliegt.
- Geplante, ausgeführte und verifizierte Schritte unterscheiden.
- Zehn Gameplay-Durchläufe nur melden, wenn eine echte Testautomatisierung sie nachweislich ausgeführt hat.
- Das Modell ist klein; Änderungen sorgfältig prüfen und Tests nicht überspringen.
AGENTS
cat > "$APP_DIR/INSTALL_OPENCODE_DE.md" <<'DOC'
# NEXUS CLAW für OpenCode + Ollama
1. Ollama installieren und den Dienst starten.
2. `ollama pull qwen2.5-coder:1.5b`
3. `ollama create nexus-claw:1.5b -f Modelfile`
4. `cd ~/NEXUS_CLAW && opencode`
5. Prüfen: `python3 doctor.py` und `python3 -m unittest discover -s tests -v`

OpenCode verwendet in `opencode.json` den lokalen Endpunkt `http://127.0.0.1:11434/v1`. Je nach Version können Provider-/Modellnamen Anpassungen erfordern.

Build-Adapter bleiben standardmäßig deaktiviert und Build-Aufgaben leer. Das Modelfile gibt keine zusätzlichen Berechtigungen. Kein automatischer Push und keine Builds während der Installation.
DOC
say "Validiere OpenCode-JSON ..."
python3 - "$APP_DIR/opencode.json" <<'PY'
import json, sys
json.load(open(sys.argv[1], encoding="utf-8"))
print("opencode.json: gültiges JSON")
PY
if command -v ollama >/dev/null 2>&1; then
  say "Lade Basismodell und erstelle NEXUS-Modell ..."
  ollama pull "$BASE_MODEL"
  ollama create "$MODEL_NAME" -f "$APP_DIR/Modelfile"
else
  say "Ollama nicht gefunden. Dateien installiert; Modell-Erstellung übersprungen."
  printf 'Nach Installation von Ollama ausführen:\n  ollama pull %s\n  ollama create %s -f "%s/Modelfile"\n' "$BASE_MODEL" "$MODEL_NAME" "$APP_DIR"
fi
say "Installation abgeschlossen."
printf '\nProjektordner: %s\n' "$APP_DIR"
printf 'OpenCode starten: cd "%s" && opencode\n' "$APP_DIR"
printf 'Dashboard starten: cd "%s" && python3 nexus_claw.py\n' "$APP_DIR"
printf 'Modell direkt testen: ollama run %s\n' "$MODEL_NAME"
printf '\nKeine Git-Commits, Pushes oder Projekt-Builds wurden gestartet.\n'
